  "Benvenuto! Da qui parte ogni giornata: «Inizia partita» (tasto giallo) la giochi tu, «Simula» la gioca il computer. «Questa settimana» ti dice cosa sistemare prima di partire. La colonna a lato porta alle altre sezioni.":"Willkommen! Hier beginnt jeder Spieltag: „Spiel starten“ (gelbe Taste) spielst du selbst, „Simulieren“ spielt der Computer. „Diese Woche“ sagt dir, was vor dem Start zu klären ist. Die Spalte an der Seite führt zu den anderen Bereichen.",
  "Gli sponsor della stagione":"Die Sponsoren der Saison",
  "Tre aziende vogliono il loro marchio sui cartelloni del tuo campo. Scegli il contratto: la quota fissa si paga durante il campionato. I bonus dipendono dai risultati di fine stagione.":"Drei Firmen wollen ihre Marke auf den Werbebanden deines Platzes. Wähle den Vertrag: Der feste Betrag wird während der Liga gezahlt. Die Boni hängen von den Ergebnissen am Saisonende ab.",
