  ": la condizione fisica; chi è scarico rende meno e si infortuna più facilmente.":": die körperliche Fitness; wer ausgelaugt ist, leistet weniger und verletzt sich leichter.",
  ": le due linee (attacco: ricevi il pull; difesa: lo tiri). Chi sta in entrambe non riposa mai: rende 7 punti in meno e si stanca il doppio.":": die zwei Linien (Angriff: du empfängst den Pull; Abwehr: du wirfst ihn). Wer in beiden steht, ruht nie: Er spielt 7 Punkte schwächer und ermüdet doppelt.",
