  "Seleziona fino a 3 giocatori per il lavoro individuale: i giovani crescono di più. Sotto 45 di condizione allenarsi può causare infortuni.":"Wähle bis zu 3 Spieler für das Einzeltraining: Junge wachsen stärker. Unter 45 Fitness kann Training zu Verletzungen führen.",
  "Tutta la squadra":"Ganzes Team",
  "Una volta a giornata. Ogni seduta costa 7 di condizione a tutti (media attuale 100); il Recupero ne ridà 18. Normale: l’equilibrio di sempre.":"Einmal pro Spieltag. Jede Einheit kostet alle 7 Fitness (aktueller Schnitt 100); die Erholung gibt 18 zurück. Normal: die gewohnte Balance.",
