  "Programma automatico":"Autoprogramm",
  "Spento":"Aus",
  "Se lo accendi, a ogni sessione il gioco fa da solo la seduta di squadra e i 3 lavori individuali: Recupero se la squadra è scarica, altrimenti l’indirizzo scelto qui. Priorità individuali: nessuna (si segnano nella scheda del giocatore, parte Sviluppo).":"Wenn du es einschaltest, macht das Spiel bei jeder Einheit das Teamtraining und die 3 Einzeltrainings selbst: Erholung, wenn das Team ausgelaugt ist, sonst der hier gewählte Schwerpunkt. Einzelprioritäten: keine (du markierst sie im Spielerprofil, Bereich Entwicklung).",
