  "Nessun punteggio e nessun cronometro: si riparte da fermo dopo ogni meta o turnover, con l’energia sempre piena.":"Kein Spielstand und keine Uhr: Nach jedem Punkt oder Turnover geht es aus dem Stand weiter, die Energie ist immer voll.",
