  "10 lanci senza difesa: 10 punti a presa, +5 se guadagni almeno 15 metri, 20 se è una meta.":"10 Würfe ohne Abwehr: 10 Punkte pro Fang, +5 bei mindestens 15 Metern Raumgewinn, 20 für einen Fang in der Endzone.",
  "Break":"Break",
  "8 lanci col marcatore addosso: 15 punti per ogni passaggio riuscito sul lato che lui chiude, 3 sul lato aperto.":"8 Würfe mit dem Marker vor dir: 15 Punkte für jeden angekommenen Pass auf die Seite, die er zumacht, 3 auf die offene Seite.",
  "Huck e duelli":"Hucks und Duelle",
  "8 lanci lunghi contro la difesa: contano solo le prese con almeno 25 metri guadagnati (tanti punti quanti i metri, +15 in meta).":"8 lange Würfe gegen die Abwehr: Es zählen nur Fänge mit mindestens 25 Metern Raumgewinn (so viele Punkte wie Meter, +15 in der Endzone).",
  "Difesa e tuffi":"Abwehr und Layouts",
  "6 azioni avversarie da fermare: 30 punti se il disco lo recupera il difensore che stai guidando, 10 se lo recupera un compagno, 0 se segnano.":"6 gegnerische Angriffe stoppen: 30 Punkte, wenn dein gesteuerter Verteidiger die Scheibe erobert, 10, wenn ein Mitspieler es tut, 0, wenn sie punkten.",
