  "Non ancora trovato · Velocità, scatto, salto e resistenza molto più alti":"Noch nicht gefunden · Viel höheres Tempo, Sprint, Sprung und Ausdauer",
  "Non ancora trovato · Vince tutti i duelli in aria e prende i dischi più alti":"Noch nicht gefunden · Gewinnt alle Luftduelle und fängt die höchsten Scheiben",
  "Non ancora trovato · Braccia lunghissime: intercetta molto più facilmente":"Noch nicht gefunden · Sehr lange Arme: fängt viel leichter Scheiben ab",
  "Non ancora trovato · Guida il disco in volo col dito: cambia la direzione, non la distanza":"Noch nicht gefunden · Lenkt die Scheibe im Flug mit dem Finger: ändert die Richtung, nicht die Weite",
  "Non ancora trovato · Si sdoppia: tu sai qual è il vero, gli avversari no. La copia serve solo a distrarre":"Noch nicht gefunden · Teilt sich in zwei: Du weißt, welcher der echte ist, die Gegner nicht. Die Kopie dient nur zur Ablenkung",
  "Non ancora trovato · Un’onda di freddo rallenta gli avversari che ha intorno":"Noch nicht gefunden · Eine Kältewelle bremst die Gegner in seiner Nähe",
  "Non ancora trovato · Gli avversari si stancano molto più in fretta":"Noch nicht gefunden · Die Gegner ermüden viel schneller",
  "Non ancora trovato · Il vento è a favore: i tuoi lanci vanno più lontano e più dritti, quelli avversari sbandano":"Noch nicht gefunden · Der Wind ist auf deiner Seite: Deine Würfe fliegen weiter und gerader, die gegnerischen schlingern",
  "Non ancora trovato · In difesa lo stall avversario corre e i cerchi rallentano; in attacco tutto va al rallentatore":"Noch nicht gefunden · In der Abwehr läuft der gegnerische Stall schneller und die Kreise werden langsamer; im Angriff läuft alles in Zeitlupe",
