  "Combo mancata: tocca quando l’anello arriva sul pulsante":"Combo verpasst: Tippe, wenn der Ring den Knopf erreicht",
  "Si vince a 7 mete: la partita di sempre, una decina di minuti.":"Bis 7 Punkte: das klassische Spiel, etwa zehn Minuten.",
  "Si vince a 11 mete: contano di più cambi, energie e linee.":"Bis 11 Punkte: Wechsel, Energie und Linien zählen mehr.",
  "Si vince a 15 mete, come nelle partite vere: una maratona.":"Bis 15 Punkte, wie in echten Spielen: ein Marathon.",
  "Spirito del gioco":"Spirit of the Game",
