  "Pioggia":"Regen",
  "Neve":"Schnee",
  "Potenza":"Kraft",
  "Direzione":"Richtung",
  "Gli accessori arrivano dai pacchetti equipaggiamento: nel Negozio (2 accessori, 120 gettoni nel torneo, 160 in Sfide online), vincendo il torneo e ai traguardi di Sfide online. Il migliore si indossa da solo; i doppioni diventano gettoni.":"Gegenstände kommen aus Ausrüstungs-Packs: im Shop (2 Gegenstände, 120 Jetons im Turnier, 160 in Online-Duelle), durch den Turniersieg und bei den Punktemarken in Online-Duelle. Der beste wird automatisch angelegt; doppelte werden zu Jetons.",
  "Tra i 7 più forti in difesa":"Unter den 7 Stärksten in der Abwehr",
  "Scegli un indirizzo per tutta la squadra, poi tocca Avvia. Per i lavori individuali apri la scheda «Individuali».":"Wähle einen Schwerpunkt für das ganze Team und tippe auf Starten. Für Einzeltraining öffne den Reiter „Einzeln“.",
  "Seduta di squadra già fatta in questa giornata.":"Teameinheit an diesem Spieltag schon absolviert.",
  "In alto ci sono due schede: «Squadra» (una seduta per tutti) e «Individuali» (scegli i giocatori nell’elenco, poi l’indirizzo). Toccando un giocatore si apre da sola la scheda «Individuali».":"Oben gibt es zwei Reiter: „Team“ (eine Einheit für alle) und „Einzeln“ (wähle die Spieler in der Liste, dann den Schwerpunkt). Tippst du auf einen Spieler, öffnet sich der Reiter „Einzeln“ von selbst.",
  "Nel pannello «Cambi» una piccola D accanto al ruolo segna i 7 giocatori più forti in difesa (tra quelli non infortunati).":"Im Fenster „Wechsel“ markiert ein kleines D neben der Rolle die 7 stärksten Verteidiger (unter den nicht Verletzten).",
  "In alto due schede: «Squadra» per la seduta di tutti, «Individuali» per i giocatori scelti. Toccando un giocatore si apre da sola la seconda.":"Oben zwei Reiter: „Team“ für die Einheit aller, „Einzeln“ für ausgewählte Spieler. Tippst du auf einen Spieler, öffnet sich der zweite von selbst.",
  "Una piccola D accanto al ruolo segna i 7 più forti in difesa.":"Ein kleines D neben der Rolle markiert die 7 Stärksten in der Abwehr.",
  "bloccata":"gesperrt",
  "fatta":"erledigt",
  "Velocità, scatto, salto e resistenza molto più alti":"Viel höhere Werte bei Tempo, Sprint, Sprung und Ausdauer",
  "Vince tutti i duelli in aria e prende i dischi più alti":"Gewinnt alle Luftduelle und fängt die höchsten Scheiben",
  "Braccia lunghissime: intercetta molto più facilmente":"Riesige Arme: fängt viel leichter ab",
  "Guida il disco in volo col dito: cambia la direzione, non la distanza":"Lenke die fliegende Scheibe mit dem Finger: Die Richtung ändert sich, nicht die Distanz",
  "Si sdoppia: tu sai qual è il vero, gli avversari no. La copia serve solo a distrarre":"Teilt sich: Du weißt, wer echt ist, die Gegner nicht. Die Kopie dient nur zur Ablenkung",
  "Un’onda di freddo rallenta gli avversari che ha intorno":"Eine Kältewelle bremst die Gegner in der Nähe",
  "Gli avversari si stancano molto più in fretta":"Die Gegner ermüden viel schneller",
