  "USA Men’s Club · 48 club veri in 8 Conference da 6. Giochi 5 partite nella tua Conference e 7 contro le altre (interregionali), poi Play-in e Nationals. Niente promozioni né retrocessioni. Il numero accanto al nome è la forza del club.":"USA Men’s Club · 48 echte Clubs in 8 Conferences mit je 6. Du spielst 5 Spiele in deiner Conference und 7 gegen die anderen (überregional), dann Play-in und Nationals. Kein Auf- oder Abstieg. Die Zahl neben dem Namen ist die Stärke des Clubs.",
  "Ranking nazionale":"Nationales Ranking",
  "Nationals · 16 squadre":"Nationals · 16 Teams",
  "16 squadre: per ogni Conference le qualificate dirette e le vincitrici dei Play-in, secondo i posti della regione (da 1 a 4). 4 gironi da 4, formati con le fasce del ranking nazionale (se possibile senza club della stessa Conference nello stesso girone). Le prime vanno ai quarti, le seconde e le terze ai prequarti (2ª contro 3ª di un altro girone), le quarte sono eliminate. Poi quarti, semifinali e finale.":"16 Teams: pro Conference die direkt Qualifizierten und die Play-in-Sieger, je nach den Plätzen der Region (1 bis 4). 4 Gruppen mit je 4, gebildet aus den Töpfen des nationalen Rankings (möglichst ohne Clubs derselben Conference in einer Gruppe). Die Gruppenersten ziehen ins Viertelfinale ein, die Zweiten und Dritten ins Achtelfinale (2. gegen 3. einer anderen Gruppe), die Vierten scheiden aus. Danach Viertelfinale, Halbfinale und Finale.",
  "I qualificati si conoscono alla fine della stagione regolare.":"Die Qualifizierten stehen am Ende der Hauptrunde fest.",
  "Sale con le vittorie (di più contro avversarie forti e con margini larghi) e scende con le sconfitte. Si aggiorna dopo ogni partita, comprese le 7 interregionali. Decide quanti posti ai Nationals ha ogni regione, le teste di serie e i gironi. E = Eastern, W = Western, C = Central, S = Southern; le frecce mostrano il cambio dall’ultima giornata e da inizio stagione.":"Es steigt mit Siegen (stärker gegen starke Gegner und bei deutlichem Vorsprung) und sinkt mit Niederlagen. Es wird nach jedem Spiel aktualisiert, auch nach den 7 überregionalen. Es entscheidet, wie viele Nationals-Plätze jede Region hat, die Setzliste und die Gruppen. E = Eastern, W = Western, C = Central, S = Southern; die Pfeile zeigen die Veränderung seit dem letzten Spieltag und seit Saisonbeginn.",
