  "Avversarie ancora più attente, con +6 a tutte le statistiche; la traiettoria del lancio si vede solo all’inizio.":"Noch aufmerksamere Gegner mit +6 auf alle Werte; die Flugbahn des Wurfs ist nur am Anfang sichtbar.",
  "Non potrai cambiarla durante la carriera.":"Während der Karriere kannst du sie nicht ändern.",
  "Allenamenti una volta ogni 2 partite. Avversarie che leggono i mismatch e si adattano un po’ al tuo gioco, con +2 a tutte le statistiche. Non potrai cambiarla durante la carriera.":"Training alle 2 Spiele. Gegner, die Mismatches erkennen und sich etwas an dein Spiel anpassen, mit +2 auf alle Werte. Während der Karriere kannst du sie nicht ändern.",
  "Allenamenti una volta ogni 2 partite. Avversarie che leggono i mismatch e si adattano un po’ al tuo gioco, con +2 a tutte le statistiche. Si sceglie all’inizio della carriera e non si può cambiare.":"Training alle 2 Spiele. Gegner, die Mismatches erkennen und sich etwas an dein Spiel anpassen, mit +2 auf alle Werte. Wird zu Beginn der Karriere gewählt und lässt sich nicht ändern.",
  "Allenamenti una volta ogni 3 partite. Avversarie che decidono, si posizionano e reagiscono meglio, con +4 a tutte le statistiche. Non potrai cambiarla durante la carriera.":"Training alle 3 Spiele. Gegner, die besser entscheiden, sich besser stellen und besser reagieren, mit +4 auf alle Werte. Während der Karriere kannst du sie nicht ändern.",
  "Allenamenti una volta ogni 3 partite. Avversarie che decidono, si posizionano e reagiscono meglio, con +4 a tutte le statistiche. Si sceglie all’inizio della carriera e non si può cambiare.":"Training alle 3 Spiele. Gegner, die besser entscheiden, sich besser stellen und besser reagieren, mit +4 auf alle Werte. Wird zu Beginn der Karriere gewählt und lässt sich nicht ändern.",
  "Avversarie ancora più attente, con +6 a tutte le statistiche; la traiettoria del lancio si vede solo all’inizio. Non potrai cambiarla durante la carriera.":"Noch aufmerksamere Gegner mit +6 auf alle Werte; die Flugbahn des Wurfs ist nur am Anfang sichtbar. Während der Karriere kannst du sie nicht ändern.",
