  "Fila al centro. Apertura: uno viene sotto sul lato aperto, uno va lungo sull’altro. Forte contro l’uomo, soffre la zona.":"Reihe in der Mitte. Auftakt: Einer kommt auf der offenen Seite entgegen, einer geht auf der anderen tief. Stark gegen Manndeckung, schwach gegen Zone.",
  "Cutter in linea larga. Apertura: il cutter interno va lungo, quello accanto viene incontro. Allarga e batte la zona; contro l’uomo che forza dentro fatica.":"Cutter in breiter Linie. Auftakt: Der innere Cutter geht tief, der daneben kommt entgegen. Zieht auseinander und schlägt die Zone; tut sich schwer gegen Manndeckung, die nach innen forct.",
  "Tutti spaziati: molti tagli corti. Buono contro gli aiuti, la zona lo chiude.":"Alle verteilt: viele kurze Cuts. Gut gegen Poaches, die Zone macht es zu.",
  "Cutter in fila su un lato: mezzo campo libero per i tagli in isolamento. Solido contro ogni marcatura a uomo, meno efficace contro la zona.":"Cutter in einer Reihe auf einer Seite: das halbe Feld frei für Iso-Cuts. Solide gegen jede Manndeckung, weniger wirksam gegen Zone.",
  "Tre handler che si passano il disco in diagonale correndosi davanti. Guadagna metri contro la zona; contro gli aiuti i passaggi corti si complicano.":"Drei Handler, die sich die Scheibe diagonal zuspielen und aneinander vorbeilaufen. Bringt Meter gegen Zone; Poaches erschweren die kurzen Pässe.",
  "Sequenza: un cutter taglia verso il disco, poi taglio in meta o di rientro. Il più efficace, ma se lo ripeti l’IA lo riconosce. Si segue alla lettera con Visione alta.":"Abfolge: Ein Cutter schneidet zur Scheibe, dann ein Cut in die Endzone oder zurück. Am wirksamsten, aber wenn du es wiederholst, erkennt es die KI. Wird bei hoher Übersicht genau befolgt.",
  "Sequenza: quattro cutter in fila larga. Due vengono incontro, uno va lungo; di solito chi è andato lungo torna incontro e poi si lancia lungo a chi va in meta. Si segue alla lettera con Visione alta.":"Abfolge: vier Cutter in breiter Reihe. Zwei kommen entgegen, einer geht tief; meist kommt der tiefe zurück und dann geht ein Weitwurf auf den, der in die Endzone läuft. Wird bei hoher Übersicht genau befolgt.",
  "Il marcatore chiude il centro: il disco va verso la linea laterale.":"Der Marker macht die Mitte zu: Die Scheibe geht Richtung Seitenlinie.",
  "Il marcatore chiude la linea laterale: lanci verso il centro.":"Der Marker macht die Linie zu: Würfe gehen zur Mitte.",
  "Tre sul disco a coppa, quattro dietro per chiudere gli spazi.":"Drei als Cup an der Scheibe, vier dahinter, um die Räume zu schließen.",
  "Chi marca un uomo lontano dal disco scala sulle linee di passaggio: più intercetti, ma un taglio improvviso lo trova in ritardo.":"Wer einen Spieler weit weg von der Scheibe deckt, rückt in die Passwege: mehr Interceptions, aber bei einem plötzlichen Cut kommt er zu spät.",
