  "La dirigenza è preoccupata: i conti sono in rosso. Finché non rientri il mercato è fermo, niente strutture né staff, e il morale ne risente. Vendi una riserva o aspetta i prossimi incassi.":"Der Vorstand ist besorgt: Die Kasse ist im Minus. Bis du das ausgleichst, ruht der Markt, keine Anlagen und kein Staff, und die Moral leidet. Verkauf einen Reservisten oder warte auf die nächsten Einnahmen.",
