  "Tre livelli (N1, N2, N3), girone unico di sola andata. N1: playoff fra le prime 4, prime 3 all’EUCF. N2 e N3: 1ª promossa, 2ª-5ª spareggio per la promozione. Due promosse e due retrocesse per livello.":"Drei Ligen (N1, N2, N3), einfache Runde. N1: Playoffs der ersten 4, die ersten 3 zur EUCF. N2 und N3: Der 1. steigt auf, Platz 2–5 spielen um den Aufstieg. Je zwei Auf- und Absteiger pro Liga.",
  "N1: 12 squadre, girone unico di sola andata, playoff fra le prime 6, prime 3 all’EUCF, retrocedono le ultime 2. N2: due gironi geografici da 12, playoff promozione fra le prime 2 di ogni girone, salgono le 2 finaliste.":"N1: 12 Teams, einfache Runde, Playoffs der ersten 6, die ersten 3 zur EUCF, die letzten 2 steigen ab. N2: zwei regionale Gruppen zu je 12, Aufstiegs-Playoffs der ersten 2 jeder Gruppe, die 2 Finalisten steigen auf.",
  "Tre livelli a girone unico di sola andata. 1. Liga: playoff fra le prime 4, prime 3 all’EUCF, retrocedono le ultime 2. 2. Liga: promosse le prime 2, retrocedono le ultime 3. 3. Liga: promosse le prime 3.":"Drei Ligen in einfacher Runde. 1. Liga: Playoffs der ersten 4, die ersten 3 zur EUCF, die letzten 2 steigen ab. 2. Liga: die ersten 2 steigen auf, die letzten 3 ab. 3. Liga: die ersten 3 steigen auf.",
