  "tocca una carta e scegli il potenziamento: ogni carta ne ha al massimo 4 (2 per linea), il prezzo è accanto al nome":"tipp auf eine Karte und wähle die Verbesserung: jede Karte hat höchstens 4 (2 pro Zeile), der Preis steht neben dem Namen",
  "tocca una riserva per scartarla e recuperare gettoni (i titolari non si scartano)":"tipp auf einen Reservisten, um ihn auszusortieren und Jetons zurückzubekommen (Stammspieler bleiben)",
  "i potenziamenti si sbloccano quando arrivi a 1100 punti: fino ad allora usa i gettoni per i pacchetti":"Verbesserungen gibt es ab 1100 Punkten: bis dahin nutz die Jetons für Packs",
  "i titolari non si scartano: toglilo prima dai titolari.":"Stammspieler kann man nicht aussortieren: nimm ihn erst aus der Startaufstellung.",
  "hai già 7 titolari: togline uno prima di aggiungerne un altro.":"du hast schon 7 Stammspieler: nimm einen raus, bevor du einen neuen dazunimmst.",
  "Campioni! Hai vinto il torneo e ottieni il Super pacchetto e un pacchetto equipaggiamento.":"Champions! Du hast das Turnier gewonnen und bekommst das Super-Pack und ein Ausrüstungspack.",
  "Riscuoti":"Einlösen",
  "Epico!":"Episch!",
  "Leggenda!":"Legende!",
  "Super pacchetto!":"Super-Pack!",
  "Nuovo eroe!":"Neuer Held!",
  "Tocca lo schermo, trascina il dito ALL’INDIETRO come una fionda e rilascia: il disco parte nella direzione opposta. Più trascini, più va lontano.":"Berühre den Bildschirm, zieh den Finger wie bei einer Schleuder NACH HINTEN und lass los: Die Scheibe fliegt in die Gegenrichtung. Je weiter du ziehst, desto weiter fliegt sie.",
  "Tocca un compagno: gli chiedi di smarcarsi (VIENI o LUNGO). Lancia verso dove sta correndo, non dove si trova.":"Tipp auf einen Mitspieler: Du forderst ihn zum Freilaufen auf (KOMM oder TIEF). Wirf dorthin, wohin er läuft, nicht wo er steht.",
  "Ora un difensore ti marca e conta fino a 10: se arriva in fondo perdi il disco. Lancia sul lato che lascia libero, lontano dalle sue braccia.":"Jetzt deckt dich ein Verteidiger und zählt bis 10: Ist er am Ende, verlierst du die Scheibe. Wirf auf die offene Seite, weg von seinen Armen.",
  "Ora c’è tutta la difesa. Si segna ricevendo il disco nella zona di meta avversaria (a destra). Avanza con passaggi sicuri o prova il lancio lungo.":"Jetzt steht die ganze Abwehr. Punkte gibt es, wenn du die Scheibe in der gegnerischen Endzone (rechts) fängst. Rück mit sicheren Pässen vor oder versuch den Weitwurf.",
  "Qui provi la difesa manuale: trascina per muovere il difensore con l’anello azzurro e resta tra il tuo uomo e il disco. Quando compare il cerchio che si stringe, premi la mano (handblock) o TUFFO mentre arriva sull’anello interno.":"Hier probierst du die manuelle Abwehr: Zieh, um den Verteidiger mit dem hellblauen Ring zu bewegen, und bleib zwischen deinem Gegenspieler und der Scheibe. Wenn der schrumpfende Kreis erscheint, drück die Hand (Handblock) oder LAYOUT, sobald er den inneren Ring erreicht.",
  "Ogni meta comincia col pull, in due tocchi. Primo tocco: ferma la POTENZA nel verde. Secondo tocco: ferma la DIREZIONE al centro. Sul campo vedi dove cadrà il disco e che pull sarebbe: cerca il GRAN PULL, ben in fondo alla meta.":"Jeder Punkt beginnt mit dem Pull, in zwei Tipps. Erster Tipp: Stopp die KRAFT im Grünen. Zweiter Tipp: Stopp die RICHTUNG in der Mitte. Auf dem Feld siehst du, wo die Scheibe landet und was für ein Pull es wäre: Ziel ist der SUPER-PULL, tief in der Endzone.",
