  "Il timeout (uno a partita) azzera lo stall e fa recuperare energia.":"Das Timeout (eins pro Spiel) setzt den Stall-Count zurück und gibt Energie.",
  "Con più Sparo il lanciatore arriva più lontano: lo vedi dall’arco rosso mentre mira.":"Mit mehr Weitwurf wirft der Werfer weiter: Du siehst es beim Zielen am roten Bogen.",
  "Controlla il meteo prima di partire: con vento forte i lanci lunghi sono più difficili.":"Check vor dem Start das Wetter: Bei starkem Wind sind weite Würfe schwerer.",
