  "Questa è la rosa con cui parti. «gen.» = giocatore generato dal gioco, non presente nelle fonti.":"Das ist der Kader, mit dem du startest. „gen.“ = vom Spiel erzeugter Spieler, nicht in den Quellen.",
  "Questa è la rosa con cui parti. Gli Overall e i ruoli con pochi dati sono stimati. «gen.» = giocatore generato dal gioco, non presente nelle fonti.":"Das ist der Kader, mit dem du startest. Overall-Werte und Rollen mit wenig Daten sind geschätzt. „gen.“ = vom Spiel erzeugter Spieler, nicht in den Quellen.",
  "EUCF: in corso":"EUCF: läuft",
  "Salgono le 2 finaliste.":"Die 2 Finalisten steigen auf.",
  ". In casa incassi i biglietti: lo stadio ha":". Zu Hause kassierst du die Tickets: Das Stadion hat",
  "di viaggio; in campo neutro (tornei, finali) i biglietti si dividono a metà. Lo sponsor paga durante il campionato. La lega premia ogni vittoria, di più nelle partite importanti.":"Reisekosten; auf neutralem Platz (Turniere, Finals) werden die Ticketeinnahmen geteilt. Der Sponsor zahlt während der Liga. Die Liga belohnt jeden Sieg, bei wichtigen Spielen mehr.",
