  "La reputazione decide chi accetta di venire; morale e affiatamento spostano un poco la forma dei tuoi in partita.":"Der Ruf entscheidet, wer kommen will; Moral und Teamchemie verschieben die Form deiner Spieler im Spiel ein wenig.",
